def get_ppt_generation(pptGenerationId, accessId, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0102000" if __import__("os").path.isdir("./environment_mix/0102000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], True
        if isinstance(obj, list):
            return obj, False
        return [], False

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        # simple, stable id generation
        ts = int(time.time() * 1000)
        rnd = os.urandom(8).hex()
        return f"{prefix}_{ts:x}{rnd}"

    def _log_request(api_rows, wrapped, access_key_id, request_body, response_body, http_status, success, ppt_generation_id=None, youtube_transcript_id=None):
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("msr"),
            "access_key_id": access_key_id,
            "tool_name": "get_ppt_generation",
            "request_body": request_body if isinstance(request_body, dict) else {},
            "response_body": response_body,
            "http_status": http_status,
            "success": bool(success),
            "latency_ms": latency_ms,
            "ppt_generation_id": ppt_generation_id,
            "youtube_transcript_id": youtube_transcript_id,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_rows.append(row)
        _save("api_requests.json", {"rows": api_rows} if wrapped else api_rows)

    # Validate inputs
    if not isinstance(pptGenerationId, str) or not pptGenerationId.strip():
        return _err("VALIDATION_ERROR", "pptGenerationId must be a non-empty string.", field="pptGenerationId")
    if not isinstance(accessId, str) or not accessId.strip():
        return _err("VALIDATION_ERROR", "accessId must be a non-empty string.", field="accessId")

    ppt_id_in = pptGenerationId.strip()
    access_in = accessId.strip()

    access_keys_obj = _load("access_keys.json")
    ppt_obj = _load("ppt_generations.json")
    api_obj = _load("api_requests.json")

    access_rows, _ = _rows(access_keys_obj)
    ppt_rows, ppt_wrapped = _rows(ppt_obj)
    api_rows, api_wrapped = _rows(api_obj)

    # Authenticate accessId: vendor requires validity; do NOT require active for read tools.
    access_row = None
    for ak in access_rows:
        if isinstance(ak, dict) and (ak.get("access_id") == access_in or ak.get("id") == access_in):
            access_row = ak
            break

    if not access_row:
        resp = _err("UNAUTHORIZED", "accessId is invalid or not permitted.", accessId=accessId)
        _log_request(api_rows, api_wrapped, None, {"pptGenerationId": pptGenerationId, "accessId": accessId}, resp, 401, False)
        return resp

    # Find job (must exist)
    job = None
    for r in ppt_rows:
        if isinstance(r, dict) and r.get("id") == ppt_id_in:
            job = r
            break

    if not job:
        resp = _err("NOT_FOUND", "PPT generation not found or not visible to this accessId.", pptGenerationId=pptGenerationId)
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId}, resp, 404, False)
        return resp

    # Authorization: job must belong to this access key
    if job.get("access_key_id") != access_row.get("id"):
        resp = _err("NOT_FOUND", "PPT generation not found or not visible to this accessId.", pptGenerationId=pptGenerationId)
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId}, resp, 404, False)
        return resp

    # Return full job as stored
    body = {"pptGeneration": job}
    _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId}, body, 200, True, ppt_generation_id=job.get("id"), youtube_transcript_id=job.get("youtube_transcript_id"))
    return body

def list_ppt_generations(accessId, status=None, createdAfter=None, createdBefore=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0102000" if __import__("os").path.isdir("./environment_mix/0102000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if not isinstance(accessId, str) or not accessId.strip():
        return _err("VALIDATION_ERROR", "accessId is required and must be a non-empty string.", field="accessId")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of queued|running|succeeded|failed|cancelled.", field="status")

    def _parse_dt_param(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)

    ca = _parse_dt_param(createdAfter, "createdAfter")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt_param(createdBefore, "createdBefore")
    if isinstance(cb, dict) and "error" in cb:
        return cb

    if pageSize is None:
        pageSize = 20
    if not isinstance(pageSize, int):
        return _err("VALIDATION_ERROR", "pageSize must be an integer.", field="pageSize")
    if pageSize < 1 or pageSize > 100:
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 100.", field="pageSize")

    if pageToken is not None:
        if not isinstance(pageToken, str) or not pageToken.strip():
            return _err("VALIDATION_ERROR", "pageToken must be a non-empty string.", field="pageToken")

    accessId_in = accessId

    access_keys = _load("access_keys.json")
    ppt_gens = _load("ppt_generations.json")
    api_reqs = _load("api_requests.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        rand = os.urandom(10).hex()
        ts = int(time.time() * 1000)
        return f"{prefix}_{ts:x}{rand}"

    def _log_request(access_key_id, success, http_status, response_body):
        latency_ms = max(0, int((time.time() - t0) * 1000))
        api_reqs.append({
            "id": _new_id("msr"),
            "access_key_id": access_key_id,
            "tool_name": "create_ppt_from_text",  # schema enum limitation
            "request_body": {
                "accessId": accessId_in,
                "status": status,
                "createdAfter": createdAfter,
                "createdBefore": createdBefore,
                "pageSize": pageSize,
                "pageToken": pageToken
            },
            "response_body": response_body,
            "http_status": http_status,
            "success": bool(success),
            "latency_ms": latency_ms,
            "ppt_generation_id": None,
            "youtube_transcript_id": None,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })

    # Authenticate access key
    ak = None
    for r in access_keys:
        if not isinstance(r, dict):
            continue
        if r.get("access_id") == accessId_in or r.get("id") == accessId_in:
            ak = r
            break
    if not ak:
        err = _err("UNAUTHORIZED", "accessId does not match any access key.")
        _log_request(None, False, 401, err)
        _save("api_requests.json", api_reqs)
        return err
    if ak.get("status") != "active":
        err = _err("UNAUTHORIZED", "accessId is invalid, suspended, or revoked.")
        _log_request(ak.get("id"), False, 401, err)
        _save("api_requests.json", api_reqs)
        return err

    access_key_id = ak.get("id")

    # Request quota
    window_start = now - datetime.timedelta(hours=24)
    req_count = 0
    for rr in api_reqs:
        if not isinstance(rr, dict):
            continue
        if rr.get("access_key_id") != access_key_id:
            continue
        dt = _parse_dt(rr.get("created_at"))
        if dt is None or dt < window_start:
            continue
        req_count += 1

    limit = ak.get("daily_request_limit")
    if not isinstance(limit, int) or limit < 0:
        limit = 0
    if req_count >= limit:
        err = _err("QUOTA_EXCEEDED", "daily_request_limit exceeded for this accessId.", limit=limit, window_hours=24)
        _log_request(access_key_id, False, 429, err)
        _save("api_requests.json", api_reqs)
        return err

    # Filter and sort (reverse chronological by created_at)
    rows = []
    for g in ppt_gens:
        if not isinstance(g, dict):
            continue
        if g.get("access_key_id") != access_key_id:
            continue
        if status is not None and g.get("status") != status:
            continue
        g_created = _parse_dt(g.get("created_at"))
        if ca is not None and (g_created is None or not (g_created > ca)):
            continue
        if cb is not None and (g_created is None or not (g_created < cb)):
            continue
        rows.append(g)

    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    # Pagination: pageToken is last seen id
    start_idx = 0
    if pageToken:
        for i, r in enumerate(rows):
            if r.get("id") == pageToken:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + pageSize]
    has_more = start_idx + pageSize < len(rows)
    next_cursor = page[-1].get("id") if has_more and page else None

    resp = {
        "pptGenerations": page,
        "page": {
            "total": len(rows),
            "page_size": pageSize,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        }
    }

    _log_request(access_key_id, True, 200, resp)
    _save("api_requests.json", api_reqs)
    return resp

def cancel_ppt_generation(pptGenerationId, accessId, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0102000" if __import__("os").path.isdir("./environment_mix/0102000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], True
        if isinstance(obj, list):
            return obj, False
        return [], False

    def _new_id(prefix):
        ts = int(time.time() * 1000)
        rnd = os.urandom(8).hex()
        return f"{prefix}_{ts:x}{rnd}"

    def _log_request(api_rows, wrapped, access_key_id, request_body, response_body, http_status, success, ppt_generation_id=None, youtube_transcript_id=None):
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("msr"),
            "access_key_id": access_key_id,
            "tool_name": "cancel_ppt_generation",
            "request_body": request_body if isinstance(request_body, dict) else {},
            "response_body": response_body,
            "http_status": http_status,
            "success": bool(success),
            "latency_ms": latency_ms,
            "ppt_generation_id": ppt_generation_id,
            "youtube_transcript_id": youtube_transcript_id,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_rows.append(row)
        _save("api_requests.json", {"rows": api_rows} if wrapped else api_rows)

    # Validate inputs
    if not isinstance(pptGenerationId, str) or not pptGenerationId.strip():
        return _err("VALIDATION_ERROR", "pptGenerationId must be a non-empty string.", field="pptGenerationId")
    if not isinstance(accessId, str) or not accessId.strip():
        return _err("VALIDATION_ERROR", "accessId must be a non-empty string.", field="accessId")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength=500.", field="reason")

    ppt_id_in = pptGenerationId.strip()
    access_in = accessId.strip()
    reason_in = reason.strip() if isinstance(reason, str) else None

    access_keys_obj = _load("access_keys.json")
    ppt_obj = _load("ppt_generations.json")
    api_obj = _load("api_requests.json")

    access_rows, _ = _rows(access_keys_obj)
    ppt_rows, ppt_wrapped = _rows(ppt_obj)
    api_rows, api_wrapped = _rows(api_obj)

    # Authenticate accessId (must be valid). Cancellation permitted only for active keys.
    access_row = None
    for ak in access_rows:
        if isinstance(ak, dict) and (ak.get("access_id") == access_in or ak.get("id") == access_in):
            access_row = ak
            break

    if not access_row:
        resp = _err("UNAUTHORIZED", "accessId is invalid or not permitted.", accessId=accessId)
        _log_request(api_rows, api_wrapped, None, {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, resp, 401, False)
        return resp

    if access_row.get("status") != "active":
        resp = _err("UNAUTHORIZED", "accessId is not active and cannot cancel PPT generations.", rule="access_keys.status must be 'active' to cancel")
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, resp, 401, False)
        return resp

    # Find job and verify ownership
    job_idx = None
    job = None
    for i, r in enumerate(ppt_rows):
        if isinstance(r, dict) and r.get("id") == ppt_id_in:
            job_idx = i
            job = r
            break

    if not job or job.get("access_key_id") != access_row.get("id"):
        resp = _err("NOT_FOUND", "PPT generation not found or not visible to this accessId.", pptGenerationId=pptGenerationId)
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, resp, 404, False)
        return resp

    status = job.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        resp = _err("CONFLICT", "PPT generation is already in a terminal state and cannot be cancelled.", status=status)
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, resp, 409, False, ppt_generation_id=job.get("id"), youtube_transcript_id=job.get("youtube_transcript_id"))
        return resp

    # Allowed transitions: queued/running -> cancelled
    if status not in ("queued", "running"):
        resp = _err("INVALID_TRANSITION", "Cancellation is only allowed from queued or running states.", from_status=status, to_status="cancelled")
        _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, resp, 409, False, ppt_generation_id=job.get("id"), youtube_transcript_id=job.get("youtube_transcript_id"))
        return resp

    # Mutate and persist
    new_job = dict(job)
    new_job["status"] = "cancelled"
    if not new_job.get("finished_at"):
        new_job["finished_at"] = now_iso
    new_job["updated_at"] = now_iso
    # Optional observability: store reason in error_message if present and empty (no schema field for cancel reason)
    if reason_in:
        prior_msg = new_job.get("error_message")
        if not prior_msg:
            new_job["error_message"] = f"Cancelled: {reason_in}"[:1000]

    ppt_rows[job_idx] = new_job
    _save("ppt_generations.json", {"rows": ppt_rows} if ppt_wrapped else ppt_rows)

    body = {"pptGeneration": new_job}
    _log_request(api_rows, api_wrapped, access_row.get("id"), {"pptGenerationId": pptGenerationId, "accessId": accessId, "reason": reason}, body, 200, True, ppt_generation_id=new_job.get("id"), youtube_transcript_id=new_job.get("youtube_transcript_id"))
    return body

