def get_youtube_transcript_status(ytUrl, accessId, language=None, **_extra):
    import json, os, datetime, time, urllib.parse, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0102000" if __import__("os").path.isdir("./environment_mix/0102000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if not isinstance(ytUrl, str) or not ytUrl.strip():
        return _err("VALIDATION_ERROR", "ytUrl must be a non-empty string.", field="ytUrl")
    if not isinstance(accessId, str) or not accessId.strip():
        return _err("VALIDATION_ERROR", "accessId must be a non-empty string.", field="accessId")
    if language is not None:
        if not isinstance(language, str):
            return _err("VALIDATION_ERROR", "language must be a string.", field="language")
        if len(language.strip()) < 2 or len(language.strip()) > 16:
            return _err("VALIDATION_ERROR", "language must be between 2 and 16 characters.", field="language")

    ytUrl_in = ytUrl
    accessId_in = accessId
    lang = language.strip() if isinstance(language, str) and language.strip() else None

    def _parse_video_id(url):
        try:
            u = urllib.parse.urlsplit(url.strip())
        except Exception:
            return None
        host = (u.netloc or "").lower()
        path = u.path or ""
        qs = urllib.parse.parse_qs(u.query or "")
        vid = None
        if "youtube.com" in host:
            if path == "/watch":
                vid = qs.get("v", [None])[0]
            elif path.startswith("/shorts/"):
                vid = path.split("/shorts/", 1)[1].split("/", 1)[0] or None
            elif path.startswith("/embed/"):
                vid = path.split("/embed/", 1)[1].split("/", 1)[0] or None
        elif host in ("youtu.be", "www.youtu.be"):
            vid = path.lstrip("/").split("/", 1)[0] or None
        if not vid:
            return None
        vid = vid.strip()
        if not re.fullmatch(r"[A-Za-z0-9_-]{6,64}", vid):
            return None
        return vid

    video_id = _parse_video_id(ytUrl_in)
    if not video_id:
        return _err("VALIDATION_ERROR", "ytUrl is not a valid YouTube video URL.", field="ytUrl")

    access_keys = _load("access_keys.json")
    youtube_tx = _load("youtube_transcripts.json")
    api_reqs = _load("api_requests.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        rand = os.urandom(10).hex()
        ts = int(time.time() * 1000)
        return f"{prefix}_{ts:x}{rand}"

    def _log_request(access_key_id, success, http_status, response_body, youtube_transcript_id=None):
        latency_ms = max(0, int((time.time() - t0) * 1000))
        api_reqs.append({
            "id": _new_id("msr"),
            "access_key_id": access_key_id,
            "tool_name": "get_youtube_transcript",
            "request_body": {"ytUrl": ytUrl_in, "accessId": accessId_in, "language": language},
            "response_body": response_body,
            "http_status": http_status,
            "success": bool(success),
            "latency_ms": latency_ms,
            "ppt_generation_id": None,
            "youtube_transcript_id": youtube_transcript_id,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })

    # Authenticate access key (active required)
    ak = None
    for r in access_keys:
        if not isinstance(r, dict):
            continue
        if r.get("access_id") == accessId_in or r.get("id") == accessId_in:
            ak = r
            break
    if not ak:
        err = _err("UNAUTHORIZED", "accessId does not match any access key.")
        _log_request(None, False, 401, err)
        _save("api_requests.json", api_reqs)
        return err
    if ak.get("status") != "active":
        err = _err("UNAUTHORIZED", "accessId is invalid, suspended, or revoked.")
        _log_request(ak.get("id"), False, 401, err)
        _save("api_requests.json", api_reqs)
        return err

    access_key_id = ak.get("id")

    # Quota: daily_request_limit and daily_transcript_limit (policy applies here)
    window_start = now - datetime.timedelta(hours=24)
    req_count = 0
    tx_count = 0
    for rr in api_reqs:
        if not isinstance(rr, dict):
            continue
        if rr.get("access_key_id") != access_key_id:
            continue
        dt = _parse_dt(rr.get("created_at"))
        if dt is None or dt < window_start:
            continue
        req_count += 1
        if rr.get("tool_name") == "get_youtube_transcript":
            tx_count += 1

    req_limit = ak.get("daily_request_limit")
    tx_limit = ak.get("daily_transcript_limit")
    if not isinstance(req_limit, int) or req_limit < 0:
        req_limit = 0
    if not isinstance(tx_limit, int) or tx_limit < 0:
        tx_limit = 0

    if req_count >= req_limit:
        err = _err("QUOTA_EXCEEDED", "daily_request_limit exceeded for this accessId.", limit=req_limit, window_hours=24)
        _log_request(access_key_id, False, 429, err)
        _save("api_requests.json", api_reqs)
        return err
    if tx_count >= tx_limit:
        err = _err("QUOTA_EXCEEDED", "daily_transcript_limit exceeded for this accessId.", limit=tx_limit, window_hours=24)
        _log_request(access_key_id, False, 429, err)
        _save("api_requests.json", api_reqs)
        return err

    # Read only; do not force refetch
    row = None
    for tr in youtube_tx:
        if not isinstance(tr, dict):
            continue
        if tr.get("video_id") == video_id and tr.get("language") == lang:
            row = tr
            break

    if row is None:
        # Return empty/unknown as NOT_FOUND? This endpoint description says "return typed error when status unavailable/error",
        # but if no record exists, treat as NOT_FOUND with video_id.
        err = _err("NOT_FOUND", "No transcript record exists for this video.", video_id=video_id, language=lang)
        _log_request(access_key_id, False, 404, err, youtube_transcript_id=None)
        _save("api_requests.json", api_reqs)
        return err

    st = row.get("status")
    if st == "fetched":
        resp = {"youtubeTranscript": row}
        _log_request(access_key_id, True, 200, resp, youtube_transcript_id=row.get("id"))
        _save("api_requests.json", api_reqs)
        return resp

    if st in ("unavailable", "error"):
        code = "NOT_FOUND" if st == "unavailable" else "CONFLICT"
        http_status = 404 if st == "unavailable" else 502
        err = _err(code, "Transcript is unavailable." if st == "unavailable" else "Transcript is in error state.", video_id=video_id, language=lang, status=st, error_code=row.get("error_code"), error_message=row.get("error_message"))
        _log_request(access_key_id, False, http_status, err, youtube_transcript_id=row.get("id"))
        _save("api_requests.json", api_reqs)
        return err

    resp = {"youtubeTranscript": row}
    _log_request(access_key_id, True, 200, resp, youtube_transcript_id=row.get("id"))
    _save("api_requests.json", api_reqs)
    return resp
